import os
import hashlib
import hmac
import unicodedata
import tempfile
import json
from pathlib import Path
from flask import Flask, request, jsonify, abort
from werkzeug.utils import secure_filename
import threading

app = Flask(__name__)

# Do not fall back to a hardcoded/predictable secret. Require it to be provided
# via the environment so tokens cannot be forged with a known key.
SESSION_SECRET = os.environ.get('SESSION_SECRET')
if not SESSION_SECRET:
    raise RuntimeError(
        "SESSION_SECRET environment variable must be set to a strong random value"
    )
UPLOAD_BASE = os.environ.get('UPLOAD_BASE', '/var/app/uploads')
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

_lock = threading.Lock()


def generate_session_token(user_id: str) -> str:
    """Generate HMAC-based session token."""
    payload = f"{user_id}:{os.urandom(16).hex()}"
    sig = hmac.new(SESSION_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"


def verify_session(token: str) -> dict:
    """Verify session token and return user info."""
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, sig = parts
    expected = hmac.new(SESSION_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, expected):
        return None
    user_id = payload.split(':')[0]
    return {'user_id': user_id}


def sanitize_path_component(name: str) -> str:
    """Sanitize a path component to prevent directory traversal.

    Normalizes Unicode to NFC form, then validates.
    """
    # Normalize to NFC for consistent comparison
    normalized = unicodedata.normalize('NFC', name)

    # Block obvious traversal attempts
    if '..' in normalized or normalized.startswith('/'):
        raise ValueError(f"Invalid path component: {name}")

    # Block null bytes
    if '\x00' in normalized:
        raise ValueError("Null byte in path")

    # Only allow certain characters
    allowed_extra = set('-_. ')
    for ch in normalized:
        if not (ch.isalnum() or ch in allowed_extra):
            raise ValueError(f"Disallowed character in path: {repr(ch)}")

    return normalized  # Return normalized name for filesystem operation


def resolve_user_directory(user_id: str, subfolder: str) -> Path:
    """Resolve the upload directory for a user with subfolder."""
    base = Path(UPLOAD_BASE)
    user_dir = base / secure_filename(user_id)

    # Sanitize subfolder - this checks the NFC-normalized version
    clean_subfolder = sanitize_path_component(subfolder)

    # Use the sanitized normalized value for path construction
    target = user_dir / clean_subfolder

    # Verify the resolved path is within user directory
    resolved = target.resolve()
    user_resolved = user_dir.resolve()
    if not str(resolved).startswith(str(user_resolved)):
        raise ValueError("Path traversal detected")

    # Ensure directory exists
    target.mkdir(parents=True, exist_ok=True)

    return target


def validate_file_metadata(metadata: dict) -> bool:
    """Validate uploaded file metadata."""
    required = ['filename', 'content_type', 'size']
    for field in required:
        if field not in metadata:
            return False
    if metadata['size'] > MAX_FILE_SIZE:
        return False
    if not metadata['filename']:
        return False
    return True


@app.route('/api/upload', methods=['POST'])
def upload_file():
    """Handle file upload with session verification."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        abort(401)

    session = verify_session(auth[7:])
    if not session:
        abort(401)

    user_id = session['user_id']

    # Get subfolder from request
    subfolder = request.form.get('subfolder', 'default')

    try:
        target_dir = resolve_user_directory(user_id, subfolder)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    f = request.files['file']
    if not f.filename:
        return jsonify({'error': 'Empty filename'}), 400

    safe_name = secure_filename(f.filename)
    if not safe_name:
        return jsonify({'error': 'Invalid filename'}), 400

    filepath = target_dir / safe_name

    with _lock:
        f.save(str(filepath))

    return jsonify({
        'status': 'uploaded',
        'path': str(filepath.relative_to(Path(UPLOAD_BASE))),
        'size': os.path.getsize(str(filepath))
    })


@app.route('/api/files', methods=['GET'])
def list_files():
    """List files in user's upload directory."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        abort(401)

    session = verify_session(auth[7:])
    if not session:
        abort(401)

    user_id = session['user_id']
    subfolder = request.args.get('subfolder', 'default')

    try:
        target_dir = resolve_user_directory(user_id, subfolder)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    files = []
    if target_dir.exists():
        for item in target_dir.iterdir():
            if item.is_file():
                files.append({
                    'name': item.name,
                    'size': item.stat().st_size
                })

    return jsonify({'files': files, 'directory': subfolder})


@app.route('/api/read', methods=['GET'])
def read_file():
    """Read a file from user's upload directory."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        abort(401)

    session = verify_session(auth[7:])
    if not session:
        abort(401)

    user_id = session['user_id']
    subfolder = request.args.get('subfolder', 'default')
    filename = request.args.get('filename', '')

    if not filename:
        return jsonify({'error': 'No filename specified'}), 400

    try:
        target_dir = resolve_user_directory(user_id, subfolder)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    safe_name = secure_filename(filename)
    filepath = target_dir / safe_name

    if not filepath.exists():
        return jsonify({'error': 'File not found'}), 404

    with open(str(filepath), 'r') as fh:
        content = fh.read()

    return jsonify({'filename': safe_name, 'content': content})


if __name__ == '__main__':
    os.makedirs(UPLOAD_BASE, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
